css.value:
linear-gradient(
        var(--group-trigger-button-color-content-primary) var(--group-trigger-button-number-0)
          var(--group-trigger-button-number-0)
      )
      content-box,
    linear-gradient(
      var(--group-trigger-button-color-content-primary) var(--group-trigger-button-number-0)
        var(--group-trigger-button-number-0)
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-state-overlay-hover),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-state-overlay-pressed),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-color-surface-surface)
        var(--group-trigger-button-state-overlay-hover),
      transparent
    )

inset var(--group-trigger-button-number-0) var(--group-trigger-button-number-0)
    var(--group-trigger-button-number-0) var(--group-trigger-button-state-overlay-spread)
    color-mix(
      in srgb,
      var(--group-trigger-button-color-surface-surface)
        var(--group-trigger-button-state-overlay-pressed),
      transparent
    )

light-dark(
    color-mix(
      in srgb,
      var(--group-trigger-button-intent-fg) var(--group-trigger-button-tertiary-foreground-hover),
      var(--group-trigger-button-color-content-primary)
    ),
    var(--group-trigger-button-intent-fg)
  )
